installer-gui-script.script:
function checkInstalledVersion() {
  var installed = system.files.plistAtPath('/Applications/TwistCast.app/Contents/Info.plist');
  if (!installed) return true;
  if (installed.CFBundleIdentifier != 'app.twist.cast') {
    my.result.type = 'Fatal';
    my.result.message = system.localizedString('INSTALL_CONFLICT');
    return false;
  }
  if (system.compareVersions(installed.CFBundleShortVersionString, '@VERSION@') > 0 ||
      system.compareVersions(installed.CFBundleVersion, '@BUILD@') > 0) {
    my.result.type = 'Fatal';
    my.result.message = system.localizedString('NEWER_INSTALLED');
    return false;
  }
  return true;
}
